ALTER TABLE public.audit_requests ADD COLUMN instant_breakdown jsonb;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, preferences jsonb NOT NULL DEFAULT '{}'::jsonb);
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read_own ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY profiles_insert_own ON public.profiles FOR INSERT TO authenticated WITH CHECK (id = auth.uid());
CREATE POLICY profiles_update_own ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read_own ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.is_audit_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles r JOIN auth.users u ON u.id=r.user_id WHERE r.user_id=auth.uid() AND r.role='admin' AND lower(u.email)='premuimxlabs@gmail.com' AND u.email_confirmed_at IS NOT NULL); $$;
REVOKE ALL ON FUNCTION public.is_audit_owner() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_audit_owner() TO authenticated, service_role;
GRANT SELECT ON public.audit_requests TO authenticated;
CREATE POLICY audit_owner_read ON public.audit_requests FOR SELECT TO authenticated USING (public.is_audit_owner());
CREATE POLICY audit_owner_screenshots ON storage.objects FOR SELECT TO authenticated USING (bucket_id='audit-screenshots' AND public.is_audit_owner());
CREATE FUNCTION public.initialize_audit_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id) ON CONFLICT(id) DO NOTHING; IF lower(NEW.email)='premuimxlabs@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT(user_id,role) DO NOTHING; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.initialize_audit_account() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER initialize_audit_account AFTER INSERT OR UPDATE OF email_confirmed_at,email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.initialize_audit_account();
INSERT INTO public.profiles(id) SELECT id FROM auth.users ON CONFLICT(id) DO NOTHING;
INSERT INTO public.user_roles(user_id,role) SELECT id,'admin'::public.app_role FROM auth.users WHERE lower(email)='premuimxlabs@gmail.com' AND email_confirmed_at IS NOT NULL ON CONFLICT(user_id,role) DO NOTHING;
CREATE TABLE public.audit_ai_state (id boolean PRIMARY KEY DEFAULT true CHECK(id), paused boolean NOT NULL DEFAULT false, reason text, status_code integer);
GRANT ALL ON public.audit_ai_state TO service_role;
ALTER TABLE public.audit_ai_state ENABLE ROW LEVEL SECURITY;